app_css:
.tool-app-readscore { color: #3f0d1c; max-width: 860px; }
.tool-app-readscore .rs-text { width: 100%; box-sizing: border-box; border: 1px solid #fecdd3; border-radius: 10px; padding: 12px; font-size: 14px; line-height: 1.6; font-family: inherit; resize: vertical; }
.tool-app-readscore .rs-toolbar { display: flex; gap: 10px; margin: 10px 0 16px; }
.tool-app-readscore .rs-btn { background: #E11D48; color: #fff; border: none; border-radius: 10px; padding: 9px 16px; font-size: 14px; font-weight: 700; cursor: pointer; }
.tool-app-readscore .rs-btn:hover { background: #be123c; }
.tool-app-readscore .rs-btn-ghost { background: #fff1f2; color: #E11D48; }
.tool-app-readscore .rs-btn-ghost:hover { background: #ffe4e6; }
.tool-app-readscore .rs-stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(130px, 1fr)); gap: 10px; margin: 0 0 16px; }
.tool-app-readscore .rs-stat { background: #fff1f2; border-radius: 10px; padding: 12px 14px; display: flex; flex-direction: column; gap: 4px; }
.tool-app-readscore .rs-stat strong { font-size: 22px; color: #881337; }
.tool-app-readscore .rs-stat-label { font-size: 12px; font-weight: 600; color: #9f1239; }
.tool-app-readscore .rs-readability { display: grid; grid-template-columns: 2fr 1fr; gap: 10px; margin: 0 0 18px; }
.tool-app-readscore .rs-ease-card { background: #fff1f2; border-radius: 10px; padding: 14px 16px; display: flex; flex-direction: column; gap: 6px; }
.tool-app-readscore .rs-ease-card strong { font-size: 30px; color: #881337; }
.tool-app-readscore .rs-ease-track { height: 10px; background: #ffe4e6; border-radius: 6px; overflow: hidden; }
.tool-app-readscore .rs-ease-bar { height: 100%; width: 0%; background: linear-gradient(90deg, #be123c, #fb7185, #34d399); border-radius: 6px; transition: width 0.3s ease; }
.tool-app-readscore .rs-ease-label { font-size: 13px; color: #9f1239; }
.tool-app-readscore h4 { margin: 18px 0 6px; font-size: 15px; color: #881337; }
.tool-app-readscore .rs-hint { font-size: 13px; color: #9f1239; margin: 0 0 10px; }
.tool-app-readscore .rs-smap { display: flex; flex-direction: column; gap: 5px; margin-bottom: 8px; }
.tool-app-readscore .rs-srow { display: flex; align-items: center; gap: 8px; }
.tool-app-readscore .rs-sbar { height: 14px; border-radius: 7px; background: #34d399; min-width: 3px; }
.tool-app-readscore .rs-sbar.rs-warn { background: #fbbf24; }
.tool-app-readscore .rs-sbar.rs-long { background: #f43f5e; }
.tool-app-readscore .rs-swords { font-size: 12px; color: #9f1239; min-width: 64px; }
.tool-app-readscore .rs-stop { font-size: 12px; color: #881337; font-weight: 700; }
.tool-app-readscore .rs-empty { font-size: 14px; color: #9f1239; background: #fff1f2; border-radius: 10px; padding: 14px; }
.tool-app-readscore .rs-topwords { display: flex; flex-wrap: wrap; gap: 8px; }
.tool-app-readscore .rs-chip { background: #fff1f2; border-radius: 999px; padding: 6px 14px; font-size: 14px; font-weight: 600; color: #881337; }
.tool-app-readscore .rs-chip span { color: #be123c; font-weight: 800; margin-right: 6px; }
@media (max-width: 560px) { .tool-app-readscore .rs-readability { grid-template-columns: 1fr; } }

app_js:
(function () {
  'use strict';
  function $(id) { return document.getElementById(id); }
  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }
  var STOP = { the:1, a:1, an:1, and:1, or:1, but:1, of:1, to:1, in:1, on:1, for:1, with:1, at:1, by:1, from:1, as:1, is:1, are:1, was:1, were:1, be:1, been:1, being:1, have:1, has:1, had:1, do:1, does:1, did:1, will:1, would:1, can:1, could:1, should:1, may:1, might:1, must:1, it:1, its:1, this:1, that:1, these:1, those:1, i:1, you:1, he:1, she:1, we:1, they:1, them:1, his:1, her:1, our:1, their:1, my:1, your:1, me:1, him:1, us:1, so:1, not:1, no:1, yes:1, if:1, then:1, than:1, too:1, very:1, just:1, about:1, into:1, over:1, after:1, before:1, between:1, through:1, during:1, such:1, only:1, own:1, same:1, also:1, well:1, there:1, their:1, what:1, which:1, who:1, whom:1, when:1, where:1, why:1, how:1, all:1, any:1, both:1, each:1, few:1, more:1, most:1, other:1, some:1, up:1, out:1, one:1, two:1, get:1, got:1, make:1, made:1, like:1 };
  var DEMO = 'Great writing is clear writing. Most sentences should be short enough to hold in one breath. When a sentence runs on for line after line, piling clause on clause until the reader has forgotten how it began, the point gets buried and the reader gives up. ReadScore measures how hard your text is to read. Paste anything in and fix what is flagged.';
  function syllables(word) {
    word = String(word).toLowerCase().replace(/[^a-z]/g, '');
    if (!word) return 0;
    if (word.length <= 3) return 1;
    var groups = word.match(/[aeiouy]+/g) || [];
    var n = groups.length;
    if (word.slice(-1) === 'e') n -= 1;
    if (word.length > 2 && word.slice(-2) === 'le' && !/[aeiouy]/.test(word.charAt(word.length - 3))) n += 1;
    return Math.max(1, n);
  }
  function sentencesOf(text) {
    var parts = String(text).match(/[^.!?\n]+[.!?]+[\"\u201d)]?/g) || [];
    var out = [];
    for (var i = 0; i < parts.length; i++) {
      var s = parts[i].trim();
      if (s) out.push(s);
    }
    return out;
  }
  function wordsOf(text) {
    var m = String(text).match(/\S+/g);
    return m || [];
  }
  function analyze(text) {
    var words = wordsOf(text);
    var sents = sentencesOf(text);
    var paras = String(text).split(/\n\s*\n/).filter(function (p) { return p.trim().length > 0; });
    var syl = 0, i;
    for (i = 0; i < words.length; i++) syl += syllables(words[i]);
    var chars = String(text).replace(/\s/g, '').length;
    var wps = sents.length ? words.length / sents.length : 0;
    var spw = words.length ? syl / words.length : 0;
    var ease = 206.835 - 1.015 * wps - 84.6 * spw;
    var grade = 0.39 * wps + 11.8 * spw - 15.59;
    ease = Math.max(0, Math.min(100, ease));
    grade = Math.max(0, grade);
    return {
      words: words, sentences: sents, paras: paras, chars: chars,
      ease: ease, grade: grade
    };
  }
  function easeLabel(e) {
    if (e >= 90) return 'Very easy to read';
    if (e >= 80) return 'Easy to read';
    if (e >= 70) return 'Fairly easy';
    if (e >= 60) return 'Standard — plain English';
    if (e >= 50) return 'Fairly difficult';
    if (e >= 30) return 'Difficult — academic or legal tone';
    return 'Very difficult to read';
  }
  function gradeLabel(g) {
    if (g <= 0) return '';
    if (g < 6) return 'Readable by a 5th grader';
    if (g < 9) return 'Middle-school level';
    if (g < 13) return 'High-school level';
    return 'College level and up';
  }
  function fmtTime(minutes) {
    if (minutes <= 0) return '—';
    if (minutes < 1) return '< 1 min';
    var m = Math.round(minutes);
    if (m < 60) return m + ' min';
    var h = Math.floor(m / 60);
    var r = m % 60;
    return h + 'h ' + (r < 10 ? '0' : '') + r + 'm';
  }
  function topWords(words) {
    var counts = {}, i, w;
    for (i = 0; i < words.length; i++) {
      w = String(words[i]).toLowerCase().replace(/[^a-z]/g, '');
      if (w.length < 3 || STOP[w]) continue;
      counts[w] = (counts[w] || 0) + 1;
    }
    var arr = [];
    for (w in counts) { if (counts.hasOwnProperty(w)) arr.push([w, counts[w]]); }
    arr.sort(function (a, b) { return b[1] - a[1]; });
    return arr.slice(0, 8);
  }
  function renderEmpty(container, msg) {
    container.innerHTML = '<div class="rs-empty">' + esc(msg) + '</div>';
  }
  function render() {
    var text = $('rs-text').value;
    var has = text.trim().length > 0;
    var a = analyze(text);
    $('rs-words').textContent = has ? String(a.words.length) : '—';
    $('rs-chars').textContent = has ? String(a.chars) : '—';
    $('rs-sent').textContent = has ? String(a.sentences.length) : '—';
    $('rs-paras').textContent = has ? String(a.paras.length) : '—';
    $('rs-read').textContent = has ? fmtTime(a.words.length / 200) : '—';
    $('rs-speak').textContent = has ? fmtTime(a.words.length / 130) : '—';
    if (has && a.words.length) {
      $('rs-ease').textContent = Math.round(a.ease);
      $('rs-easebar').style.width = Math.round(a.ease) + '%';
      $('rs-easelabel').textContent = easeLabel(a.ease);
      $('rs-grade').textContent = a.grade.toFixed(1);
      $('rs-gradelabel').textContent = gradeLabel(a.grade);
    } else {
      $('rs-ease').textContent = '—';
      $('rs-easebar').style.width = '0%';
      $('rs-easelabel').textContent = '';
      $('rs-grade').textContent = '—';
      $('rs-gradelabel').textContent = '';
    }
    var smap = $('rs-smap');
    if (!has || !a.sentences.length) {
      renderEmpty(smap, 'Paste some text to see the sentence breakdown.');
    } else {
      var maxW = 1, i, counts = [];
      for (i = 0; i < a.sentences.length; i++) {
        var n = wordsOf(a.sentences[i]).length;
        counts.push(n);
        if (n > maxW) maxW = n;
      }
      var html = '';
      var longCount = 0;
      for (i = 0; i < counts.length; i++) {
        var cls = 'rs-sbar';
        if (counts[i] > 24) { cls += ' rs-long'; longCount++; }
        else if (counts[i] > 14) { cls += ' rs-warn'; }
        var width = Math.max(2, Math.round(counts[i] / maxW * 100));
        html += '<div class="rs-srow"><span class="rs-swords">' + counts[i] + ' words</span>' +
          '<div class="' + cls + '" style="width:' + width + '%"></div></div>';
      }
      if (longCount) {
        html += '<p class="rs-stop">' + longCount + (longCount === 1 ? ' sentence' : ' sentences') +
          ' over 24 words — try splitting ' + (longCount === 1 ? 'it' : 'them') + '.</p>';
      }
      smap.innerHTML = html;
    }
    var tw = $('rs-topwords');
    var tops = topWords(a.words);
    if (!has || !tops.length) {
      renderEmpty(tw, 'Common filler words filtered out — your most-used words appear here.');
    } else {
      var th = '';
      for (var j = 0; j < tops.length; j++) {
        th += '<div class="rs-chip"><span>' + tops[j][1] + '×</span>' + esc(tops[j][0]) + '</div>';
      }
      tw.innerHTML = th;
    }
  }
  $('rs-text').addEventListener('input', render);
  $('rs-clear').addEventListener('click', function () { $('rs-text').value = ''; render(); });
  $('rs-demo').addEventListener('click', function () { $('rs-text').value = DEMO; render(); });
  $('rs-text').value = DEMO;
  render();
})();
